SELECT * FROM logs WHERE EventID=1 AND (EventID=1 AND ((Image LIKE '%\\powershell.exe' ESCAPE '\' OR Image LIKE '%\\pwsh.exe' ESCAPE '\') AND (CommandLine LIKE '% -e %' ESCAPE '\' OR CommandLine LIKE '% -ec %' ESCAPE '\' OR CommandLine LIKE '% -en %' ESCAPE '\' OR CommandLine LIKE '% -enc %' ESCAPE '\' OR CommandLine LIKE '% -enco%' ESCAPE '\' OR CommandLine LIKE '% -encodedcommand %' ESCAPE '\')))
